<?php
/**
 * QPOS Cost Code v3 one-time installer.
 * Generated 2026-07-21T17:19:21Z; delete this file immediately after a successful install.
 */

@set_time_limit(120);
header('Content-Type: text/html; charset=UTF-8');

$requiredKey = 'qposclear2026';
$providedKey = isset($_GET['key']) && is_string($_GET['key']) ? $_GET['key'] : '';
if (!hash_equals($requiredKey, $providedKey)) {
    http_response_code(403);
    render_result(false, array('Access denied: supply the correct installer key.'), true);
    exit;
}

$root = realpath(dirname(__DIR__));
if ($root === false || !is_file($root . DIRECTORY_SEPARATOR . 'artisan') || !is_dir($root . DIRECTORY_SEPARATOR . 'app')) {
    http_response_code(500);
    render_result(false, array('Laravel root was not found. Upload this installer beside public/index.php.'), true);
    exit;
}

$payload = array(
    'app/Utils/ProductUtil.php' => array('sha1' => '7d9cc34ce58b9ecfbd0c6fdf7e8c4d847079d12a', 'data' => ''),
    'app/Http/Controllers/ProductController.php' => array('sha1' => '4ca24da031d8fc7a1815f0036942c2106bfd2874', 'data' => ''),
    'app/Http/Controllers/BusinessController.php' => array('sha1' => '791f4c6da982dee7b45ded8e61f0416326e19d41', 'data' => ''),
    'resources/views/business/partials/settings_costcode.blade.php' => array('sha1' => '66c1293d72e82c967f25bb5f541ad07c03be8873', 'data' => ''),
    'lang/en/lang_v1.php' => array('sha1' => '3a37fc38fd475144002d1b9e37cbadb078286340', 'data' => ''),
);

$messages = array();
$decoded = array();
$staged = array();
$backupRoot = $root . DIRECTORY_SEPARATOR . 'storage' . DIRECTORY_SEPARATOR . 'app' . DIRECTORY_SEPARATOR . 'qpos-installer-backups' . DIRECTORY_SEPARATOR . 'costcode-v3-' . gmdate('Ymd-His') . '-' . substr(sha1(uniqid('', true)), 0, 8);

try {
    // Validate every embedded file before touching the application.
    foreach ($payload as $relative => $item) {
        if (!preg_match('#^(app|resources|lang)/[A-Za-z0-9_./-]+$#', $relative) || strpos($relative, '..') !== false) {
            throw new RuntimeException('Unsafe payload path: ' . $relative);
        }
        $content = base64_decode($item['data'], true);
        if ($content === false || !hash_equals($item['sha1'], sha1($content))) {
            throw new RuntimeException('Embedded payload validation failed: ' . $relative);
        }
        $decoded[$relative] = $content;
    }

    if (!is_dir($backupRoot) && !mkdir($backupRoot, 0755, true) && !is_dir($backupRoot)) {
        throw new RuntimeException('Could not create backup directory.');
    }

    // Back up current files, then stage replacements in their destination directories.
    foreach ($decoded as $relative => $content) {
        $destination = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
        $directory = dirname($destination);
        if (!is_dir($directory)) {
            throw new RuntimeException('Destination directory is missing: ' . $relative);
        }
        if (is_link($destination)) {
            throw new RuntimeException('Refusing to replace symbolic link: ' . $relative);
        }
        if (is_file($destination)) {
            $backup = $backupRoot . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
            if (!is_dir(dirname($backup)) && !mkdir(dirname($backup), 0755, true) && !is_dir(dirname($backup))) {
                throw new RuntimeException('Could not create backup path for: ' . $relative);
            }
            if (!copy($destination, $backup)) {
                throw new RuntimeException('Could not back up: ' . $relative);
            }
        }
        $temporary = tempnam($directory, '.qpos-costcode-v3-');
        if ($temporary === false) {
            throw new RuntimeException('Could not stage: ' . $relative);
        }
        $staged[$relative] = $temporary;
        if (file_put_contents($temporary, $content, LOCK_EX) !== strlen($content)) {
            throw new RuntimeException('Incomplete staged write: ' . $relative);
        }
        @chmod($temporary, is_file($destination) ? (fileperms($destination) & 0777) : 0644);
        if (!hash_equals($payload[$relative]['sha1'], sha1_file($temporary))) {
            throw new RuntimeException('Staged file verification failed: ' . $relative);
        }
    }

    foreach ($staged as $relative => $temporary) {
        $destination = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
        if (!rename($temporary, $destination)) {
            throw new RuntimeException('Atomic replacement failed: ' . $relative);
        }
        unset($staged[$relative]);
        clearstatcache(true, $destination);
        if (!hash_equals($payload[$relative]['sha1'], sha1_file($destination))) {
            throw new RuntimeException('Installed file verification failed: ' . $relative);
        }
        if (function_exists('opcache_invalidate')) {
            @opcache_invalidate($destination, true);
        }
        $messages[] = 'Installed and verified: ' . $relative;
    }

    $cleared = 0;
    $cacheLocations = array(
        $root . DIRECTORY_SEPARATOR . 'storage' . DIRECTORY_SEPARATOR . 'framework' . DIRECTORY_SEPARATOR . 'views',
        $root . DIRECTORY_SEPARATOR . 'storage' . DIRECTORY_SEPARATOR . 'framework' . DIRECTORY_SEPARATOR . 'cache' . DIRECTORY_SEPARATOR . 'data',
    );
    foreach ($cacheLocations as $cacheLocation) {
        $cleared += clear_cache_files($cacheLocation);
    }
    $bootstrapCache = $root . DIRECTORY_SEPARATOR . 'bootstrap' . DIRECTORY_SEPARATOR . 'cache';
    if (is_dir($bootstrapCache)) {
        foreach (array('config.php', 'events.php', 'routes.php', 'routes-v7.php', 'services.php', 'packages.php') as $cacheFile) {
            $candidate = $bootstrapCache . DIRECTORY_SEPARATOR . $cacheFile;
            if (is_file($candidate) && !is_link($candidate) && @unlink($candidate)) {
                $cleared++;
            }
        }
    }
    $messages[] = 'Cleared ' . $cleared . ' compiled Blade/cache file(s).';
    if (function_exists('opcache_reset')) {
        @opcache_reset();
        $messages[] = 'Requested an OPcache reset.';
    }
    $messages[] = 'Backup saved under storage/app/qpos-installer-backups/' . basename($backupRoot) . '/';
    render_result(true, $messages, true);
} catch (Throwable $error) {
    foreach ($staged as $temporary) {
        if (is_file($temporary)) {
            @unlink($temporary);
        }
    }
    http_response_code(500);
    $messages[] = 'ERROR: ' . $error->getMessage();
    $messages[] = 'No shell commands were used. Review the backup directory before retrying.';
    render_result(false, $messages, true);
}

function clear_cache_files($directory)
{
    if (!is_dir($directory) || is_link($directory)) {
        return 0;
    }
    $count = 0;
    $iterator = new RecursiveIteratorIterator(
        new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS),
        RecursiveIteratorIterator::CHILD_FIRST
    );
    foreach ($iterator as $item) {
        if ($item->isLink()) {
            continue;
        }
        if ($item->isFile() && $item->getFilename() !== '.gitignore' && @unlink($item->getPathname())) {
            $count++;
        }
    }
    return $count;
}

function render_result($success, $messages, $showDeleteWarning)
{
    $title = $success ? 'Cost Code v3 installed' : 'Cost Code v3 installer failed';
    $color = $success ? '#137333' : '#b3261e';
    echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">';
    echo '<title>' . htmlspecialchars($title, ENT_QUOTES, 'UTF-8') . '</title>';
    echo '<style>body{font:16px/1.5 system-ui,sans-serif;background:#f5f7fa;color:#202124;margin:0;padding:32px}main{max-width:780px;margin:auto;background:#fff;border-radius:12px;padding:28px;box-shadow:0 2px 14px #0002}h1{color:' . $color . ';margin-top:0}li{margin:.45rem 0}.warning{background:#fff3cd;border:1px solid #f1cf65;border-radius:8px;padding:14px;font-weight:700}code{word-break:break-all}</style></head><body><main>';
    echo '<h1>' . htmlspecialchars($title, ENT_QUOTES, 'UTF-8') . '</h1><ul>';
    foreach ($messages as $message) {
        echo '<li>' . htmlspecialchars($message, ENT_QUOTES, 'UTF-8') . '</li>';
    }
    echo '</ul>';
    if ($showDeleteWarning) {
        echo '<p class="warning">Security warning: delete <code>qpos_install_costcode_v3.php</code> from the server now.</p>';
    }
    if ($success) {
        echo '<p>Hard-refresh the browser, then go to Settings &gt; Cost Code.</p>';
    }
    echo '</main></body></html>';
}
